window.kbPageData["views/entry/k-2c0ba297ccc21e63"] = {"key":"entry/k-2c0ba297ccc21e63","state":{"route":"entry/k-2c0ba297ccc21e63"},"node":{"id":"k-2c0ba297ccc21e63","mode":"k","title":"加快推动全面绿色转型①","type":"事实与事件","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["生态环境"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"（九）加快推动全面绿色转型①。以碳达峰碳中和②为牵引，协同推进降碳、减污、扩\n绿、增长，增强绿色发展动能。\n加强生态环境综合治理。深入打好蓝天、碧水、净土保卫战③，制定实施空气质量持续\n改善行动计划，推进县城和农村黑臭水体治理，加强重点行业污染地块风险管控。强化新污\n染物治理，实施固体废物综合治理行…","sources":[{"id":"b8427c514a3ee369","label":"加快推动全面绿色转型①","topic":"年度政府工作","category":"时政","text":"（九）加快推动全面绿色转型①。以碳达峰碳中和②为牵引，协同推进降碳、减污、扩\n绿、增长，增强绿色发展动能。\n加强生态环境综合治理。深入打好蓝天、碧水、净土保卫战③，制定实施空气质量持续\n改善行动计划，推进县城和农村黑臭水体治理，加强重点行业污染地块风险管控。强化新污\n染物治理，实施固体废物综合治理行动。完善多元化生态补偿机制，拓展生态产品价值实现\n渠道。加强生物多样性保护，实施好长江十年禁渔④。坚持山水林田湖草沙一体化保护和系\n统治理，实施自然保护地整合优化，推进国家公园建设，扎实推进“三北”工程攻坚战⑤，\n让人民群众身边的山更绿、水更清。\n大力发展绿色低碳经济。完善促进绿色低碳发展政策，实施重点行业提质降本降碳行动，\n深入推进零碳园区和工厂建设⑥。设立国家低碳转型基金，培育氢能、绿色燃料等新增长点。\n有力有效管控高耗能高排放项目，加快淘汰落后产能，支持绿色低碳技术装备创新应用。完\n善资源总量管理和全面节约制度，强化再生资源循环利用。\n积极稳妥推进碳达峰碳中和。实施碳排放总量和强度双控制度⑦，完善碳排放统计核算、\n碳足迹管理体系，进一步扩大碳排放权交易市场覆盖范围。制定能源强国建设规划纲要。着\n力构建新型电力系统，加快智能电网建设，发展新型储能，扩大绿电应用。加强化石能源清\n洁高效利用。","source":{"doc":"6cbfb01fe723bba64b75","first":45,"last":45,"page":45,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-2c0ba297ccc21e63":[]}};
